/// Turns one of the strings above into (longitude, latitude) pairs.
List<(double, double)> parseOutline(String shape) {
  final points = <(double, double)>[];
  for (final pair in shape.split(' ')) {
    final parts = pair.split(',');
    if (parts.length == 2) {
      final lon = double.tryParse(parts[0]);
      final lat = double.tryParse(parts[1]);
      if (lon != null && lat != null) {
        points.add((lon, lat));
      }
    }
  }
  return points;
}
